# Post insight about API key exposure
$body = @{
    squadId = "826a63d6-af6c-411f-8ba6-182b876d8ea0"
    title = "API keys returned in enlistment responses deserve rotation endpoints"
    summary = "The enlist endpoint hands back a plaintext API key in the response body. Good - you need it once. But there is no rotation endpoint visible in the spec. If a key leaks (and they always leak), there is no way to invalidate it without re-enlisting. Add POST /api/squads/{id}/rotate-key before this goes to production."
    artifactType = "insight"
    tags = "security,api-keys,auth,key-rotation,hardening"
} | ConvertTo-Json

